INSERT INTO creatures (id, title, source, subgroup, summary, meta, portrait, tags, creature_stats, callouts, sort_order) VALUES
('c13', 'Имперский штатный солдат', 'gm', 'Великое герцогство Талабек', 'Основа имперской пехоты — регулярные войска, обученные держать строй и прикрывать друг друга. Штатные солдаты вооружаются тем, что требует текущая задача: древковым оружием для ближнего боя или огнестрельным оружием и арбалетами для дальней поддержки.', 'Угроза: низкая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/a5b31605-45eb-415d-90c0-dba0a778d60b.webp', '["стража"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 3}, {"code": "Х", "value": 3}], "speed": "Нормальная", "wounds": "4 (бронированный)", "type": "Прислужник", "skills": ["защита 4", "обычные 3"], "attacks": [{"name": "Алебарда", "range": "Ближняя", "formula": "3d/3", "damage": "5", "rounds": "2Р"}, {"name": "Арбалет", "range": "Короткая-дальняя", "formula": "3d/3", "damage": "4", "rounds": "2Р", "traits": "2 успеха для перезарядки"}, {"name": "Копьё", "range": "Короткая", "formula": "3d/3", "damage": "3", "rounds": "1Р"}, {"name": "Ружьё", "range": "Средняя-дальняя", "formula": "3d/3", "damage": "5", "rounds": "2Р", "traits": "Игнорирует броню; 3 успеха для перезарядки"}], "defenses": ["Атлетика 3d/3", "Защита 3d/4"], "abilities": [{"name": "Вспомогательное действие", "description": "Штатные войска развёртываются перекрывающимися отрядами для взаимной поддержки и помощи. Когда противник входит на ближнюю дистанцию к штатному солдату, один союзный штатный солдат или ополченец вольной роты в соседней зоне, который сам не находится на ближней дистанции от врага, может немедленно совершить рывок или произвести дистанционную атаку.", "descriptionLinks": [{"match": "ополченец вольной роты", "entryId": "c40"}]}], "equipment": [{"name": "Алебарда", "linkEntryId": "i15"}, {"name": "или Арбалет", "linkEntryId": "i38"}, {"name": "или Копьё", "linkEntryId": "i21"}, {"name": "или Ружьё", "linkEntryId": "i40"}, {"name": "Лёгкая броня", "linkEntryId": "i1"}, {"name": "Мундир", "linkEntryId": "i14"}]}'::jsonb, NULL, 8),
('c14', 'Имперский рыцарь', 'gm', 'Великое герцогство Талабек', 'Имперские рыцари — элита конных войск, присягнувшая на верность своему ордену и сюзерену. Закованные в тяжёлую броню и вооружённые рыцарским копьём, они бросаются в атаку верхом, сметая противника единым сокрушительным ударом.', 'Угроза: средняя', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/f9404e74-1184-45e3-aee8-b1f1679326bb.webp', '["рыцарь"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 4}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 3}, {"code": "В", "value": 3}, {"code": "И", "value": 3}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 4}, {"code": "Х", "value": 3}], "speed": "Нормальная", "wounds": "6 (бронированный)", "type": "Силач", "skills": ["защита 4", "обычные 3", "рукопашный бой 4", "сила воли 4"], "attacks": [{"name": "Рыцарское копьё", "range": "Ближняя", "formula": "4d/4", "damage": "4", "rounds": "1Р", "traits": "При атаке с рывка верхом даёт +1d к проверке рукопашного боя и +1 к урону"}], "defenses": ["Атлетика 2d/3", "Защита 4d/4 (щит)"], "abilities": [{"name": "Благородный скакун", "description": "Рыцари обычно вступают в бой верхом на коне. В таком случае они получают +1 к живучести, становятся быстрыми и автоматически накладывают состояние сбит с ног — до того, как цель сможет уступить позицию, — при успешной атаке с рывка на любое существо, не являющееся чудовищем.", "descriptionLinks": [{"match": "сбит с ног", "entryId": "r18"}]}, {"name": "Ради ордена", "description": "Рыцари Империи ищут славы, бросаясь в бой на врага. Любые проверки атаки, которые имперский рыцарь совершает в ходе атаки с рывка, считаются славными — при условии, что он не находится в состоянии ошеломлён.", "descriptionLinks": [{"match": "ошеломлён", "entryId": "r16"}]}], "equipment": [{"name": "Рыцарское копьё", "linkEntryId": "i35"}, {"name": "Тяжёлая броня", "linkEntryId": "i56"}, {"name": "Щит", "linkEntryId": "i55"}]}'::jsonb, '[{"title": "Пороги ран", "items": ["0 ран: —", "1 рана: получает состояние истощён.", "2 раны: побеждён."]}]'::jsonb, 9),
('c15', 'Жрец Таала', 'gm', 'Великое герцогство Талабек', 'Таал — бог диких мест, охоты и природы. Его жрецы избегают цивилизации, предпочитая леса и глушь, где выслеживают добычу и защищают дикую природу от тех, кто желает ей зла. В бою они не менее опасны: колючий кустарник и меткая стрела быстро остудят пыл незваного гостя.', 'Угроза: средняя', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/c24855b5-5180-4b3a-b16b-c30dee3b4813.webp', '["жрец", "культ"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 4}, {"code": "ДБ", "value": 4}, {"code": "С", "value": 4}, {"code": "В", "value": 4}, {"code": "И", "value": 4}, {"code": "Пр", "value": 4}, {"code": "Р", "value": 4}, {"code": "Х", "value": 4}], "speed": "Нормальная", "wounds": "5 (бронированный)", "type": "Чемпион", "skills": ["выживание 4", "лидерство 4", "метание 4", "обычные 3", "сила воли 4", "стрельба 4"], "attacks": [{"name": "Метательное копьё", "range": "Ближняя-средняя", "formula": "4d/4", "damage": "3", "rounds": "1Р"}, {"name": "Охотничий лук", "range": "Средняя-дальняя", "formula": "4d/4", "damage": "3", "rounds": "2Р"}], "defenses": ["Атлетика 4d/3"], "abilities": [{"name": "Благосклонность Таала", "description": "Жрецы Таала чувствуют себя как дома в диких местах. Любые проверки, которые они совершают, чтобы охотиться, выслеживать или незаметно пробираться через дикую местность, всегда считаются славными. Они игнорируют пересечённую местность, созданную лесами, и всегда могут определить, когда кто-то преследует их в дикой местности."}, {"name": "Густая лоза", "description": "Жрецы Таала могут призвать власть Таала над природой, чтобы помешать врагам своего бога. Действием они могут выбрать зону в пределах дальней дистанции, где есть любая растительность, — из земли прорастает колючий кустарник, который считается пересечённой местностью для всех, у кого нет благословения Таала."}], "equipment": [{"name": "Боевой лук", "linkEntryId": "i36"}, {"name": "Лёгкая броня", "linkEntryId": "i1"}, {"name": "Метательное копьё", "linkEntryId": "i4"}, {"name": "Охотничий набор", "linkEntryId": "i68"}]}'::jsonb, NULL, 10),
('c16', 'Имперский огр', 'gm', 'Огры и полурослики', 'Огры‑наёмники нанимаются на службу Империи целыми ротами — их огромная сила и живучесть делают из них грозных штурмовиков передовой линии. Одним ударом двуручного молота огр способен сбить с ног закованного в броню рыцаря, а, разъярённый, рывком в самую гущу боя он сокрушит всё, что встанет на пути.', 'Угроза: высокая', 'https://cdn.poehali.dev/projects/8ea67526-cf7e-472d-ad6c-bad53fcea4bc/bucket/adbb8de7-e75b-4cad-bc1a-e18acf3efa99.webp', '["огр"]'::jsonb, '{"characteristics": [{"code": "ББ", "value": 3}, {"code": "ДБ", "value": 3}, {"code": "С", "value": 5}, {"code": "В", "value": 5}, {"code": "И", "value": 2}, {"code": "Пр", "value": 3}, {"code": "Р", "value": 2}, {"code": "Х", "value": 2}], "speed": "Быстрая", "wounds": "6 (бронированный)", "type": "Силач", "skills": ["атлетика 3", "лидерство 3", "мощь 4", "обычные 2", "рукопашный бой 4", "сила воли 3", "стойкость 4"], "attacks": [{"name": "Грубый толчок", "range": "Ближняя", "formula": "5d/4", "damage": "2", "rounds": "1Р", "traits": "Попадания накладывают состояние сбит с ног"}, {"name": "Двуручный молот", "range": "Ближняя", "formula": "2d/4", "damage": "8", "rounds": "2Р"}, {"name": "Пистолет огра", "range": "Ближняя-средняя", "formula": "3d/2", "damage": "5", "rounds": "1Р", "traits": "Игнорирует броню; 3 успеха для перезарядки"}], "defenses": ["Атлетика 3d/3"], "abilities": [{"name": "Рывок огра", "description": "Огры врываются в бой, используя свою огромную массу, чтобы сокрушить врагов. Если они успешно проводят атаку грубым толчком в рамках атаки с рывка, то могут совершить второе действие — атаковать другим оружием."}, {"name": "Устрашающий", "description": "Огры — крупные, шумные и устрашающие существа. Когда их атаки в ближнем бою вынуждают врага уступить позицию, цель получает состояние сломлен."}, {"name": "Могучий бросок", "description": "Огры могут использовать свою невероятную силу, чтобы подбросить врагов в воздух. Если огр успешно проводит атаку грубым толчком против ошеломлённого врага, тот отлетает в точку в пределах дальней дистанции, получает рану и приобретает состояние сбит с ног."}], "equipment": [{"name": "Двуручный молот", "linkEntryId": "i34"}, {"name": "Лёгкая броня", "linkEntryId": "i1"}, {"name": "Ружьё", "linkEntryId": "i40"}]}'::jsonb, '[{"title": "Пороги ран", "items": ["0 ран: —", "1-2 раны: скорость снижена до нормальной.", "3 раны: побеждён."]}]'::jsonb, 11);